function discoveryPlacement(f:Film,birth:number,p:Demographics|null,now:number):{year:number;fit:number;familyContext:boolean}|null{
 const rule=timelineRules[f.id];if(!rule){
 const family=/animation|family/i.test(f.genres||"");const minAge=family?3:12;const releaseAge=f.year-birth;
 if(f.year>now||releaseAge<minAge-8)return null;
 const year=Math.max(f.year,birth+minAge);
 if(year>now)return null;
 return {year,fit:family&&year-birth<=17?13:releaseAge>=minAge?10:7,familyContext:false};
 }
 const firstRelease=f.year+rule.lag,releaseAge=firstRelease-birth;
 // Film-specific primary audience bands, not viewing restrictions. Earlier films may be discovered through home media.
 const nearAudience=rule.kind!=="adult"&&releaseAge>=rule.lo-4;const discoveryAge=nearAudience?Math.min(rule.peak,rule.lo+1):rule.peak;const year=Math.max(firstRelease,releaseAge<rule.lo?birth+discoveryAge:firstRelease);
 const age=year-birth;
 if(year<=now&&age>=rule.lo){
  if(rule.kind==="family"&&age<=rule.hi)return {year,fit:16-Math.abs(age-rule.peak)*.9,familyContext:false};
  if(rule.kind==="youth")return {year,fit:age<=rule.hi?16-Math.abs(age-rule.peak)*.35:Math.max(2,7-(age-rule.hi)*.22),familyContext:false};
  if(rule.kind==="adult")return {year,fit:age<18?11:15,familyContext:false};
 }
 // Childhood-focused films are not automatically assigned to teenagers or adults at release.
 // An explicitly shared child's age can create a later family-viewing invitation, never an asserted memory.
 if(rule.kind==="family"&&p?.children==="Yes"&&p.childAges?.length){
  const recorded=new Date(p.childAgesRecordedAt||p.date||Date.now()).getFullYear();
  const possibilities=p.childAges.filter(a=>a!==""&&Number.isInteger(Number(a))&&Number(a)>=0).map(a=>{
   const childBirth=recorded-Number(a);const first=Math.max(firstRelease,childBirth+rule.lo,birth+18);
   const y=Math.max(first,firstRelease<childBirth+rule.lo?childBirth+rule.peak:first);
   return {year:y,childAge:y-childBirth};
  }).filter(x=>x.year<=now&&x.childAge>=rule.lo&&x.childAge<=rule.hi).sort((a,b)=>Math.abs(a.childAge-rule.peak)-Math.abs(b.childAge-rule.peak));
  if(possibilities.length)return {year:possibilities[0].year,fit:12,familyContext:true};
 }
 return null;
}
function timelineSuggestions(profile:Demographics|null,library:Film[]){
 const chapters=lifeChapters(profile),birth=chapters[0]?.from,now=new Date().getFullYear();if(birth===undefined)return [];
 const result:{film:Film;year:number;chapter:number;later:boolean;fit:number;familyContext:boolean}[]=[];
 for(const film of library){const placement=discoveryPlacement(film,birth,profile,now);if(!placement)continue;const chapter=chapters.findIndex(ch=>placement.year>=ch.from&&placement.year<=ch.to);if(chapter>=0)result.push({film,...placement,chapter,later:placement.year>film.year+1})}
 return result;
}
